package com.vit.archds.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){return body(HttpStatus.BAD_REQUEST,"Validation failed",e.getBindingResult().getFieldErrors().stream().collect(java.util.stream.Collectors.toMap(x->x.getField(),x->x.getDefaultMessage(),(a,b)->a)));} @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<?> bad(RuntimeException e){return body(HttpStatus.BAD_REQUEST,e.getMessage(),null);} @ExceptionHandler(NoSuchElementException.class) ResponseEntity<?> notFound(Exception e){return body(HttpStatus.NOT_FOUND,e.getMessage(),null);} @ExceptionHandler(Exception.class) ResponseEntity<?> generic(Exception e){return body(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected server error",null);} private ResponseEntity<?> body(HttpStatus s,String m,Object d){Map<String,Object>x=new LinkedHashMap<>();x.put("timestamp",Instant.now());x.put("status",s.value());x.put("error",s.getReasonPhrase());x.put("message",m);if(d!=null)x.put("details",d);return ResponseEntity.status(s).body(x);}}
